CREATE OR REPLACE FUNCTION prevent_critical_equip_delete() RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM "Equipment" e
        JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
        LEFT JOIN "LightingAndSafety" ls ON e."EQUIP_CODE" = ls."equipRef"
        LEFT JOIN "WeatherAndStructure" ws ON e."EQUIP_CODE" = ws."loc_link"
        WHERE e."EQUIP_CODE" = OLD."EQUIP_CODE"
          AND e."EquipType" = 'Safety'
          AND CAST(et."type_indices"->>'safety_idx' AS numeric) / 100 > 0.75
          AND (ls."lifeSupportStat" IN ('Critical', 'Warning') 
               OR ls."O2SupplyStat" IN ('Critical', 'Warning')
               OR ws."extTempC" < 0)
    ) THEN
        RAISE EXCEPTION 'Cannot delete critical operational equipment';
    END IF;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER protect_critical_equipment
BEFORE DELETE ON "Equipment"
FOR EACH ROW
EXECUTE FUNCTION prevent_critical_equip_delete();

